// Construye la instruccion de direccion de arte a partir de la intencion y el Brand Kit.
const b = ($input.first().json.body) || {};
const marca = b.marca || {};
const ctx = b.contexto || {};
const paleta = Array.isArray(marca.paleta)
  ? marca.paleta.map(c => (c && c.nombre ? c.nombre + ' (' + c.hex + ')' : c)).filter(Boolean).join(', ')
  : '';
const reglas = Array.isArray(marca.reglas) ? marca.reglas.map(r => '- ' + r).join('\n') : '';

const instr = [
  'Eres director de arte y copywriter de una marca. A partir de una intencion y el Brand Kit, prepara una pieza para ' + (b.red || 'Instagram') + ' (formato ' + (b.ratio || '4:5') + ').',
  'Intencion del usuario: ' + (b.intencion || '') + '.',
  b.tipoPost ? 'Tipo de post: ' + b.tipoPost + '.' : '',
  b.cliente ? 'Marca: ' + b.cliente + '.' : '',
  marca.territorio ? 'Territorio de marca: ' + marca.territorio + '.' : '',
  marca.tono ? 'Tono de voz: ' + marca.tono + '.' : '',
  paleta ? 'Paleta de marca: ' + paleta + '.' : '',
  reglas ? 'Reglas de marca:\n' + reglas : '',
  ctx.centro ? 'Contexto: ' + ctx.centro + (ctx.linea ? ' (' + ctx.linea + ')' : '') + '.' : '',
  b.ajuste ? 'Ajuste pedido para esta ronda: ' + b.ajuste + '.' : '',
  'Devuelve SOLO un JSON valido con estas claves:',
  '- "prompt_imagen": prompt fotografico DETALLADO en espanol para un modelo de imagen (escena concreta, sujeto, encuadre segun el formato, luz, ambiente; coherente con la paleta y el territorio; fotorrealista y editorial, no banco de imagenes). MUY IMPORTANTE: la imagen NO debe contener ningun texto, letra, numero, logo ni marca de agua, y debe dejar espacio limpio en esquinas/margen para superponer el logo y un titular despues.',
  '- "concepto": la idea creativa en UNA frase.',
  '- "copy_texto": el texto del post (1-3 frases, en el tono de marca, sin hashtags dentro).',
  '- "hashtags": de 3 a 6 hashtags separados por espacios.',
  'Nada mas que el JSON.'
].filter(Boolean).join('\n');

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: instr }] }],
  generationConfig: { temperature: 0.85, responseMimeType: 'application/json' }
});

return [{ json: { geminiBody } }];

// Normaliza el JSON de Gemini a prompt_imagen + concepto + copy_texto + hashtags.
const j = $input.first().json;
const text = ((j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || [])
  .map(p => p.text).filter(Boolean).join('');
let o = {};
try { o = JSON.parse(text); } catch (e) { o = { prompt_imagen: text }; }
let h = o.hashtags || '';
if (Array.isArray(h)) h = h.join(' ');
return [{ json: {
  ok: true,
  prompt_imagen: o.prompt_imagen || '',
  concepto: o.concepto || '',
  copy_texto: o.copy_texto || o.caption || '',
  hashtags: h
} }];
